import os,tempfile,subprocess,time,json
script="
'use strict';
const port=Number(process.argv[2]);
const json=async(p)=>{const r=await fetch('http://127.0.0.1:'+port+p,{signal:AbortSignal.timeout(1500)});return r.json()};
function rpc(url,method,params={},timeout=2300){
 return new Promise(resolve=>{
  let done=false,ws;const timer=setTimeout(()=>finish({ok:false,reason:'timeout'}),timeout);
  function finish(data){if(done)return;done=true;clearTimeout(timer);try{ws?.close()}catch{}resolve(data)}
  try{ws=new WebSocket(url);ws.addEventListener('open',()=>ws.send(JSON.stringify({id:101,method,params})));
      ws.addEventListener('message',e=>{try{const x=JSON.parse(e.data);if(x.id===101)finish(x.error?{ok:false,reason:'cdp_error'}:{ok:true,data:x.result})}catch{finish({ok:false,reason:'bad_json'})}});
      ws.addEventListener('error',()=>finish({ok:false,reason:'websocket_error'}));
  }catch{finish({ok:false,reason:'construct_error'})}
 });
}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function main(){
 const b=await json('/json/version');
 let made=[];
 for(let i=0;i<3;i++){
  const result=await rpc(b.webSocketDebuggerUrl,'Target.createTarget',{url:'about:blank',background:true});
  made.push({ok:result.ok,id:result.data?.targetId});
 }
 const all=await json('/json/list');
 const targets=made.map(x=>all.find(t=>t.id===x.id&&t.webSocketDebuggerUrl)).filter(Boolean);
 const rounds=[];
 for(let i=0;i<5;i++){
  const res=await Promise.all(targets.map(x=>rpc(x.webSocketDebuggerUrl,'Runtime.evaluate',{expression:'2+2',returnByValue:true},1300)));
  rounds.push({round:i,ok:res.filter(x=>x.ok && x.data?.result?.value===4).length,total:res.length});
  await wait(2300);
 }
 console.log(JSON.stringify({browser:b.Browser,created:made.filter(z=>z.ok).length,matchedTargets:targets.length,rounds,allResponsive:rounds.every(x=>x.ok===3)}));
}
main().catch(e=>{console.log(JSON.stringify({error:String(e.message).slice(0,130)}));process.exitCode=1});
